1	/**
2	 * Pure transforms over the official FedRAMP feeds.
3	 * Shared by the browser (docs/js/*) and the Node CLI (tools/fedramp-data.mjs),
4	 * so the site's "live refresh" and the build-time snapshots can never disagree.
5	 *
6	 * SECURITY: this module is the single sanitization boundary for hostile
7	 * upstream input. Both the CLI snapshots and the browser's live refresh
8	 * funnel every feed through these transforms, so every string is
9	 * type-checked, control-char-stripped and length-capped HERE, every id must
10	 * match a strict pattern, and every date must be a real calendar date in a
11	 * sane range. Sanitization here is about type/length/shape — HTML escaping
12	 * is the renderer's job (see esc() in docs/js/ui.js); a poisoned feed can at
13	 * worst produce weird-looking text, never oversized payloads, control
14	 * characters, forged ids, or prototype pollution.
15	 *
16	 * Feed shapes verified against the real data 2026-08-15; see docs/data/README.md.
17	 */
18	
19	/* ======================= sanitize layer ======================= */
20	
21	const NAME_MAX = 300; // names, statuses, org strings
22	const STMT_MAX = 2000; // KSI statements
23	// C0 controls (0x00-0x1F), DEL (0x7F), and C1 controls (0x80-0x9F).
24	const CONTROL_CHARS = /[\u0000-\u001F\u007F-\u009F]/g;
25	
26	/** Must be a string → strip control chars, trim, cap length; anything else → null. */
27	const cleanStr = (v, max = NAME_MAX) => {
28	  if (typeof v !== 'string') return null;
29	  const s = v.replace(CONTROL_CHARS, '').trim();
30	  if (!s) return null;
31	  return s.length > max ? s.slice(0, max) : s;
32	};
33	
34	// Real ids seen in the feeds: F1607067912, FR2315464863, AGENCYAMAZONEW, 22-012.
35	const ID_RE = /^[A-Za-z0-9._-]{1,64}$/;
36	const FORBIDDEN_KEYS = new Set(['__proto__', 'prototype', 'constructor']);
37	
38	/** Must match the strict id pattern (and never a prototype-polluting key) → else null. */
39	const cleanId = (v) => (typeof v === 'string' && ID_RE.test(v) && !FORBIDDEN_KEYS.has(v) ? v : null);
40	
41	/** Non-negative finite integer, else the fallback. Bounds hostile numerics. */
42	const cleanCount = (v, fallback = 0) =>
43	  typeof v === 'number' && Number.isFinite(v) && v >= 0 ? Math.min(Math.trunc(v), 1_000_000_000) : fallback;
44	
45	const DATE_MIN = '1990-01-01'; // FedRAMP didn't exist before 2011; generous floor
46	
47	/**
48	 * Strict date: `YYYY-MM-DD` prefix, a REAL calendar date (Date.UTC round-trip,
49	 * so 2026-02-31 and 9999-99-99 are rejected), within [1990-01-01, today+1d].
50	 */
51	const dateOrNull = (v) => {
52	  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}/.test(v)) return null;
53	  const s = v.slice(0, 10);
54	  const y = Number(s.slice(0, 4));
55	  const m = Number(s.slice(5, 7));
56	  const d = Number(s.slice(8, 10));
57	  const t = new Date(Date.UTC(y, m - 1, d));
58	  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) return null;
59	  if (s < DATE_MIN) return null;
60	  if (s > new Date(Date.now() + 86_400_000).toISOString().slice(0, 10)) return null;
61	  return s;
62	};
63	
64	/** The feed uses the literal string "Not Active" as its null sentinel. */
65	const notSentinel = (s) => (s && s !== 'Not Active' ? s : null);
66	
67	/** Total-order string comparator (ISO dates compare correctly as strings). */
68	const cmpStr = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
69	
70	/* ======================= products ======================= */
71	
72	/** Slim the 43-field marketplace product records down to what the site uses. */
73	export function slimProducts(marketplace) {
74	  const products = Array.isArray(marketplace?.data?.Products) ? marketplace.data.Products : [];
75	  const out = [];
76	  for (const p of products) {
77	    if (p === null || typeof p !== 'object') continue;
78	    const id = cleanId(p.id);
79	    if (!id) continue; // no trustworthy id → drop the record
80	    out.push({
81	      id,
82	      csp: cleanStr(p.csp),
83	      cso: cleanStr(p.cso),
84	      offering: cleanStr(p.service_offering),
85	      status: cleanStr(p.status),
86	      impact: cleanStr(p.impact_level),
87	      authType: notSentinel(cleanStr(p.auth_type)),
88	      authDate: dateOrNull(p.auth_date),
89	      reuse: cleanCount(p.reuse),
90	      assessor: notSentinel(cleanStr(p.independent_assessor)),
91	      models: Array.isArray(p.service_model) ? p.service_model.map((m) => cleanStr(m)).filter(Boolean) : [],
92	      deployment: cleanStr(p.deployment_model),
93	      agencies: Array.isArray(p.agency_authorizations) ? p.agency_authorizations.length : 0,
94	    });
95	  }
96	  return out;
97	}
98	
99	/** Tally by key. Built via Map so hostile keys can't touch any prototype. */
100	const count = (arr, key) => {
101	  const tally = new Map();
102	  for (const item of arr) {
103	    const k = key(item);
104	    if (k == null) continue;
105	    tally.set(k, (tally.get(k) ?? 0) + 1);
106	  }
107	  return Object.fromEntries(tally);
108	};
109	
110	export const is20x = (p) => typeof p.impact === 'string' && p.impact.startsWith('20x');
111	
112	/** Program-level statistics computed from the full marketplace feed. */
113	export function computeStats(marketplace) {
114	  const slim = slimProducts(marketplace);
115	  const authorized = slim.filter((p) => p.status === 'FedRAMP Authorized');
116	  return {
117	    lastChange: cleanStr(marketplace?.meta?.last_change, 64),
118	    totals: {
119	      products: slim.length,
120	      byStatus: count(slim, (p) => p.status),
121	      byImpact: count(slim, (p) => p.impact),
122	      authorized20x: authorized.filter(is20x).length,
123	    },
124	    authsByYear: count(authorized, (p) => p.authDate?.slice(0, 4)),
125	    authsByYear20x: count(authorized.filter(is20x), (p) => p.authDate?.slice(0, 4)),
126	    topReused: [...authorized]
127	      .sort((a, b) => b.reuse - a.reuse || cmpStr(a.id, b.id))
128	      .slice(0, 15)
129	      .map((p) => ({ cso: p.cso, csp: p.csp, reuse: p.reuse, impact: p.impact })),
130	    topAssessors: Object.entries(count(authorized, (p) => p.assessor))
131	      .sort((a, b) => b[1] - a[1] || cmpStr(a[0], b[0]))
132	      .slice(0, 10)
133	      .map(([name, n]) => ({ name, count: n })),
134	  };
135	}
136	
137	/* ======================= KSI catalog ======================= */
138	
139	/** Prune the consolidated rules file to the KSI catalog the site renders. */
140	export function pruneKsi(rules) {
141	  const families = [];
142	  for (const fam of Object.values(rules?.KSI ?? {})) {
143	    if (fam === null || typeof fam !== 'object') continue;
144	    const famId = cleanId(fam.id);
145	    if (!famId) continue;
146	    const indicators = [];
147	    for (const [rawId, ind] of Object.entries(fam.indicators ?? {})) {
148	      const id = cleanId(rawId);
149	      if (!id || ind === null || typeof ind !== 'object') continue;
150	      indicators.push({
151	        id,
152	        name: cleanStr(ind.name),
153	        statement: cleanStr(ind.statement, STMT_MAX),
154	        controls: Array.isArray(ind.controls) ? ind.controls.map((c) => cleanId(c)).filter(Boolean) : [],
155	        // per-class statement overrides, when FedRAMP varies an indicator by class
156	        classes: cleanClassVariants(ind.varies_by_class),
157	      });
158	    }
159	    families.push({
160	      id: famId,
161	      name: cleanStr(fam.name),
162	      short: cleanStr(fam.short_name, 64),
163	      status: cleanStr(fam.status, 64),
164	      indicators,
165	    });
166	  }
167	  return {
168	    version: cleanStr(rules?.info?.version, 64),
169	    updated: dateOrNull(rules?.info?.last_updated),
170	    families,
171	  };
172	}
173	
174	/** Sanitize the {classKey: {statement}} variation map; hostile keys dropped. */
175	function cleanClassVariants(varies) {
176	  if (varies === null || varies === undefined || typeof varies !== 'object') return null;
177	  const out = {};
178	  for (const [k, v] of Object.entries(varies)) {
179	    const key = cleanId(k);
180	    if (!key || v === null || typeof v !== 'object') continue;
181	    out[key] = { statement: cleanStr(v.statement, STMT_MAX) };
182	  }
183	  return Object.keys(out).length ? out : null;
184	}
185	
186	/* ======================= journey engine =======================
187	 * The status changelog is messy real-world event data: migration-era backfill
188	 * (source:"migration", coarse dates), out-of-order rows, duplicate transitions,
189	 * journeys missing a start or an end, and a mixed vocabulary of 15 statuses.
190	 * Invariants enforced here:
191	 *   1. events are sorted by (transition_date, recorded_date, to_status, input
192	 *      order) — a total order, so ties are deterministic
193	 *   2. consecutive duplicates (same date + same to_status) collapse to one
194	 *   3. an "end" is the FIRST event matching END_STATUS; the "start" is the
195	 *      first event BEFORE it matching START_STATUS. Pre-process designations
196	 *      (FedRAMP Ready / "FRR") stay in the events chain — they're real
197	 *      history — but they do not start the clock
198	 *   4. duration (days) exists only when start < end; everything else is
199	 *      excluded and COUNTED, never silently dropped
200	 *   5. migration-sourced journeys are flagged (their early dates are coarser)
201	 *   6. `current` is the last event of the FULL chain, delistings included —
202	 *      a delisted service must never report its old status as current
203	 * Vocabulary verified against the live feed 2026-08-15.
204	 */
205	
206	// Authorized, FedRAMP Certified, FedRAMP Certified (In Remediation)
207	export const END_STATUS = /^(authorized$|fedramp certified)/i;
208	export const isEndStatus = (s) => typeof s === 'string' && END_STATUS.test(s);
209	
210	// In-process-type statuses that start the clock. Matches the verified
211	// vocabulary: JAB Review, Agency Review, PMO Review, Initial Program Review,
212	// Final Program Review, FedRAMP In Process, Agency In Process, Agency
213	// Authorization In Process, Initial Implementation — and deliberately
214	// EXCLUDES "FRR" (FedRAMP Ready, a pre-process readiness designation).
215	export const START_STATUS = /(in process|review|initial implementation)/i;
216	
217	const DELISTED = /no status found/i;
218	
219	// `Program` alone is NOT a 20x marker: the changelog also uses that path for
220	// pre-20x Rev5 journeys. Require the feed's explicit 20x type/path value.
221	const isPath20x = (e) => e.type === '20x' || e.path === '20x';
222	
223	/** Build per-product journeys from the raw changelog. Returns {journeys, excluded}. */
224	export function buildJourneys(changelog) {
225	  const rows = Array.isArray(changelog?.data?.certprocessstatuschangelog)
226	    ? changelog.data.certprocessstatuschangelog
227	    : [];
228	  const byProduct = new Map();
229	  let idx = 0;
230	  for (const r of rows) {
231	    if (r === null || typeof r !== 'object') continue;
232	    const id = cleanId(r.product_id);
233	    const date = dateOrNull(r.transition_date);
234	    const to = cleanStr(r.to_status);
235	    if (!id || !date || !to) continue;
236	    if (!byProduct.has(id)) byProduct.set(id, { csp: null, cso: null, evs: [] });
237	    const g = byProduct.get(id);
238	    if (!g.cso && (r.cso || r.csp)) {
239	      g.cso = cleanStr(r.cso);
240	      g.csp = cleanStr(r.csp);
241	    }
242	    g.evs.push({
243	      date,
244	      to,
245	      class: cleanStr(r.cert_class, 64),
246	      path: cleanStr(r.cert_path, 64),
247	      type: cleanStr(r.cert_type, 64),
248	      source: cleanStr(r.source, 64),
249	      recorded: cleanStr(r.recorded_date, 64) ?? '',
250	      idx: idx++,
251	    });
252	  }
253	
254	  const journeys = [];
255	  const excluded = { delistedOnly: 0, noEnd: 0, noStart: 0, invalidOrder: 0 };
256	
257	  for (const [id, group] of byProduct) {
258	    const evs = group.evs;
259	    // total order: same-instant ties resolved by recorded date, then status
260	    // text, then input position — reruns and reordered inputs agree
261	    evs.sort((a, b) => cmpStr(a.date, b.date) || cmpStr(a.recorded, b.recorded) || cmpStr(a.to, b.to) || a.idx - b.idx);
262	    const deduped = evs.filter((e, i) => i === 0 || !(e.date === evs[i - 1].date && e.to === evs[i - 1].to));
263	
264	    const migration = deduped.some((e) => e.source === 'migration');
265	    const live = deduped.filter((e) => !DELISTED.test(e.to));
266	    if (!live.length) {
267	      excluded.delistedOnly++;
268	      continue;
269	    }
270	
271	    const endIdx = live.findIndex((e) => isEndStatus(e.to));
272	    const end = endIdx === -1 ? null : live[endIdx];
273	    const startIdx = end ? live.slice(0, endIdx).findIndex((e) => START_STATUS.test(e.to)) : -1;
274	    const start = startIdx === -1 ? null : live[startIdx];
275	
276	    let days = null;
277	    if (!end) excluded.noEnd++;
278	    else if (!start) excluded.noStart++; // e.g. backfill starting at "Authorized", or FRR-only prehistory
279	    else if (end.date <= start.date) excluded.invalidOrder++;
280	    else days = Math.round((new Date(end.date) - new Date(start.date)) / 86_400_000);
281	
282	    // A later re-authorization must not relabel an earlier legacy completion.
283	    // Measured cohorts use markers only from the selected start→end interval.
284	    // Incomplete journeys use their live history for current-path UI, but never
285	    // enter duration statistics.
286	    const cohortEvents = start && end ? live.slice(startIdx, endIdx + 1) : live;
287	    const is20x = cohortEvents.some(isPath20x);
288	
289	    journeys.push({
290	      id,
291	      csp: group.csp,
292	      cso: group.cso,
293	      is20x,
294	      migration,
295	      days,
296	      start: days != null ? start.date : null,
297	      end: days != null ? end.date : null,
298	      // full chain, delistings included — see invariant 6
299	      current: deduped[deduped.length - 1].to,
300	      events: deduped.map((e) => ({ date: e.date, to: e.to, class: e.class })),
301	    });
302	  }
303	  return { journeys, excluded };
304	}
305	
306	/* ======================= journey statistics ======================= */
307	
308	/** Nearest-rank percentile over an ascending-sorted array. */
309	const percentile = (sorted, p) => sorted[Math.max(0, Math.ceil((p / 100) * sorted.length) - 1)];
310	
311	/** p10/p50/p90 for one cohort of journeys. */
312	const durationSplit = (list) => {
313	  const days = list.map((j) => j.days).sort((a, b) => a - b);
314	  if (!days.length) return { n: 0, p10: null, p50: null, p90: null };
315	  return { n: days.length, p10: percentile(days, 10), p50: percentile(days, 50), p90: percentile(days, 90) };
316	};
317	
318	const BIN = 90;
319	const MAXBIN = 12; // last bin is open-ended: 990+ days
320	
321	/** 90-day histogram; labels are inclusive ranges (0–89, 90–179, …, 990+). */
322	const buildHistogram = (measured) => {
323	  const histogram = Array.from({ length: MAXBIN }, (_, i) => ({
324	    label: i === MAXBIN - 1 ? `${i * BIN}+` : `${i * BIN}–${(i + 1) * BIN - 1}`,
325	    count: 0,
326	  }));
327	  for (const j of measured) {
328	    histogram[Math.min(MAXBIN - 1, Math.floor(j.days / BIN))].count++;
329	  }
330	  return histogram;
331	};
332	
333	/** Fastest measured journeys finishing on/after `since`, quickest first. */
334	const fastestSince = (measured, since, n) =>
335	  measured
336	    .filter((j) => j.end && j.end >= since)
337	    .sort((a, b) => a.days - b.days || cmpStr(a.id, b.id))
338	    .slice(0, n)
339	    .map((j) => ({ id: j.id, cso: j.cso, csp: j.csp, days: j.days, end: j.end, is20x: j.is20x }));
340	
341	/** Duration statistics over measured journeys, split legacy vs 20x-path. */
342	export function journeyStats({ journeys, excluded }) {
343	  const measured = journeys.filter((j) => j.days != null);
344	  return {
345	    totalWithEvents: journeys.length,
346	    measured: measured.length,
347	    excluded,
348	    all: durationSplit(measured),
349	    path20x: durationSplit(measured.filter((j) => j.is20x)),
350	    legacy: durationSplit(measured.filter((j) => !j.is20x)),
351	    histogram: buildHistogram(measured),
352	    fastest: fastestSince(measured, '2025-01-01', 12),
353	  };
354	}
355	
356	/* ======================= activity + directories ======================= */
357	
358	/** Merged live-activity feed: status transitions + dated agency reuses/ATOs. */
359	export function buildActivity(marketplace, changelog, { limit = 120 } = {}) {
360	  const max = Number.isInteger(limit) && limit > 0 ? limit : 120;
361	  const rawProducts = Array.isArray(marketplace?.data?.Products) ? marketplace.data.Products : [];
362	  const products = new Map();
363	  for (const p of rawProducts) {
364	    if (p === null || typeof p !== 'object') continue;
365	    const id = cleanId(p.id);
366	    if (id) products.set(id, p);
367	  }
368	  const out = [];
369	  for (const e of pruneChangelog(changelog)) {
370	    out.push({ date: e.date, kind: 'status', to: e.to, class: e.class, cso: e.cso, csp: e.csp });
371	  }
372	  const reuses = Array.isArray(marketplace?.data?.ReuseMapping) ? marketplace.data.ReuseMapping : [];
373	  for (const r of reuses) {
374	    if (r === null || typeof r !== 'object') continue;
375	    const date = dateOrNull(r.auth_date) ?? dateOrNull(r.ato_date);
376	    const p = products.get(cleanId(r.id));
377	    if (!date || !p) continue;
378	    out.push({
379	      date,
380	      kind: 'reuse',
381	      agency: agencyName(r),
382	      cso: cleanStr(p.cso) ?? cleanStr(p.service_offering),
383	      csp: cleanStr(p.csp),
384	    });
385	  }
386	  return out
387	    .map((e, i) => ({ ...e, idx: i }))
388	    .sort((a, b) => cmpStr(b.date, a.date) || a.idx - b.idx) // newest first; ties keep build order
389	    .slice(0, max)
390	    .map(({ idx, ...e }) => e);
391	}
392	
393	/** "Parent — Sub" display name for an agency-ish row (agencies + reuse mapping). */
394	const agencyName = (row) => {
395	  const parent = cleanStr(row.parent);
396	  const sub = cleanStr(row.sub);
397	  return parent && sub ? `${parent} — ${sub}` : parent;
398	};
399	
400	/** Slim agency directory; product references are ids, resolved client-side. */
401	export function slimAgencies(marketplace) {
402	  const agencies = Array.isArray(marketplace?.data?.Agencies) ? marketplace.data.Agencies : [];
403	  const out = [];
404	  for (const a of agencies) {
405	    if (a === null || typeof a !== 'object') continue;
406	    const id = cleanId(a.id);
407	    if (!id) continue;
408	    out.push({
409	      id,
410	      name: agencyName(a),
411	      authorizations: cleanCount(a.authorization),
412	      reuse: cleanCount(a.reuse),
413	      auths: Array.isArray(a.auths) ? a.auths.map((x) => cleanId(x?.id)).filter(Boolean) : [],
414	      reuses: Array.isArray(a.reuses) ? a.reuses.map((x) => cleanId(x?.id)).filter(Boolean) : [],
415	    });
416	  }
417	  return out;
418	}
419	
420	/** Slim + filter status-change events; newest first. */
421	export function pruneChangelog(changelog, { since = null, limit = null } = {}) {
422	  const events = Array.isArray(changelog?.data?.certprocessstatuschangelog)
423	    ? changelog.data.certprocessstatuschangelog
424	    : [];
425	  let out = events
426	    .map((e, i) =>
427	      e === null || typeof e !== 'object'
428	        ? null
429	        : {
430	            date: dateOrNull(e.transition_date),
431	            csp: cleanStr(e.csp),
432	            cso: cleanStr(e.cso),
433	            type: cleanStr(e.cert_type, 64),
434	            path: cleanStr(e.cert_path, 64),
435	            class: cleanStr(e.cert_class, 64),
436	            from: cleanStr(e.from_status),
437	            to: cleanStr(e.to_status),
438	            idx: i,
439	          },
440	    )
441	    .filter((e) => e && e.date && e.to)
442	    .sort((a, b) => cmpStr(b.date, a.date) || a.idx - b.idx) // newest first; ties keep feed order
443	    .map(({ idx, ...e }) => e);
444	  if (since) out = out.filter((e) => e.date >= since);
445	  if (limit) out = out.slice(0, limit);
446	  return out;
447	}
