175	export function relativeDate(iso) {
176	  const t = new Date(`${iso}T12:00:00`).getTime();
177	  if (!Number.isFinite(t)) return '';
178	  const days = Math.floor((Date.now() - t) / 86_400_000);
179	  if (days <= 0) return 'today';
180	  if (days === 1) return 'yesterday';
181	  if (days < 30) return `${days}d ago`;
