1	/**
2	 * Watchlist: star services, and on your next visit lead with what changed.
3	 * Pure logic (fingerprints + diff) is exported for tests; storage is a thin
4	 * versioned wrapper — schema bumps migrate or reset explicitly, never crash.
5	 *
6	 * localStorage is treated as untrusted input (shared-machine scenario):
7	 * ids are re-validated against the marketplace id format on every load and
8	 * fingerprint values are type/length-checked. Fingerprint maps use
9	 * Object.create(null) so hostile keys like "__proto__" stay inert data.
10	 */
11	
12	// Same guarded-storage contract as ui.js `storage` (Safari private mode throws
13	// on ANY localStorage access). Kept local — NOT imported from ui.js — because
14	// this module is also imported by the Node test suite, where ui.js's
15	// top-level matchMedia() call would crash. The try/catch also makes the
16	// module import-safe in Node (no global localStorage → get() returns null).
17	const storage = {
18	  get(k) {
19	    try { return localStorage.getItem(k); } catch { return null; }
20	  },
21	  set(k, v) {
22	    try { localStorage.setItem(k, v); return true; } catch { return false; }
23	  },
24	};
25	
26	const KEY = 'fedramp-watchlist';
27	const SCHEMA = 2; // v2: {schema, starred: [id], fingerprints: {id: fp}, savedAt}
28	
29	/** Marketplace id format — anything else is dropped on load. */
30	export const SAFE_ID = /^[A-Za-z0-9._-]{1,64}$/;
31	
32	const isSafeId = (id) => typeof id === 'string' && SAFE_ID.test(id);
33	const cleanField = (v) => (typeof v === 'string' && v.length <= 200 ? v : null);
34	
35	function cleanFingerprint(fp) {
36	  return {
37	    status: cleanField(fp?.status),
38	    impact: cleanField(fp?.impact),
39	    latest: cleanField(fp?.latest),
40	    latestDate: cleanField(fp?.latestDate),
41	  };
42	}
43	
44	/** What we remember about a watched service between visits. */
45	export function fingerprint(product, journey) {
46	  return {
47	    status: product?.status ?? null,
48	    impact: product?.impact ?? null,
49	    latest: journey?.events?.[journey.events.length - 1]?.to ?? null,
50	    latestDate: journey?.events?.[journey.events.length - 1]?.date ?? null,
51	  };
52	}
53	
54	/**
55	 * Compare saved fingerprints against current data.
56	 * Returns [{id, changes: [{field, from, to}]}] — only entries with changes.
57	 * A service that had real data but is absent from `current` (delisted or
58	 * gone from the feed) is reported as a `listed` change, never dropped.
59	 */
60	export function diffFingerprints(saved, current) {
61	  const out = [];
62	  for (const [id, oldFp] of Object.entries(saved ?? {})) {
63	    const newFp = current?.[id];
64	    if (!newFp) {
65	      const hadData = oldFp != null && (oldFp.status != null || oldFp.impact != null || oldFp.latest != null);
66	      if (hadData) out.push({ id, changes: [{ field: 'listed', from: 'listed', to: 'no longer in the feed' }] });
67	      continue;
68	    }
69	    const changes = [];
70	    for (const field of ['status', 'impact', 'latest']) {
71	      if (oldFp?.[field] != null && newFp[field] != null && oldFp[field] !== newFp[field]) {
72	        changes.push({ field, from: oldFp[field], to: newFp[field] });
73	      }
74	    }
75	    if (changes.length) out.push({ id, changes });
76	  }
77	  return out;
78	}
79	
80	function emptyState() {
81	  return { schema: SCHEMA, starred: [], fingerprints: Object.create(null), savedAt: null };
82	}
83	
84	export function loadWatchlist() {
85	  try {
86	    const raw = JSON.parse(storage.get(KEY) ?? 'null');
87	    // v1 stored a bare (unversioned) array of ids — check BEFORE the object
88	    // guard, otherwise arrays fail the `starred` check and migration is dead code.
89	    if (Array.isArray(raw)) return { ...emptyState(), starred: raw.filter(isSafeId) };
90	    if (!raw || typeof raw !== 'object' || !Array.isArray(raw.starred)) return emptyState();
91	    const starred = raw.starred.filter(isSafeId);
92	    const fingerprints = Object.create(null);
93	    if (raw.schema === SCHEMA && raw.fingerprints && typeof raw.fingerprints === 'object') {
94	      for (const id of starred) {
95	        if (Object.prototype.hasOwnProperty.call(raw.fingerprints, id)) {
96	          fingerprints[id] = cleanFingerprint(raw.fingerprints[id]);
97	        }
98	      }
99	    }
100	    const savedAt =
101	      raw.schema === SCHEMA && typeof raw.savedAt === 'string' && raw.savedAt.length <= 40 ? raw.savedAt : null;
102	    return { schema: SCHEMA, starred, fingerprints, savedAt };
103	  } catch {
104	    return emptyState();
105	  }
106	}
107	
108	/**
109	 * Persist. `savedAt` means "when did the user last SEE this page", not "when
110	 * did we last write" — it only advances via markVisited() (or an explicit
111	 * advanceSavedAt), so the "since your last visit (3d ago)" label survives
112	 * mid-session fingerprint commits.
113	 */
114	export function saveWatchlist(state, { advanceSavedAt = false } = {}) {
115	  const savedAt = advanceSavedAt ? new Date().toISOString() : state.savedAt ?? null;
116	  storage.set(KEY, JSON.stringify({ ...state, schema: SCHEMA, savedAt }));
117	}
118	
119	/** Record "the user visited now". Call ONCE per page load, after diffs render. */
120	export function markVisited(state) {
121	  const next = { ...state, savedAt: new Date().toISOString() };
122	  saveWatchlist(next);
123	  return next;
124	}
125	
126	export function toggleStar(state, id) {
127	  const starred = state.starred.includes(id) ? state.starred.filter((x) => x !== id) : [...state.starred, id];
128	  return { ...state, starred };
129	}
130	
131	/**
132	 * Refresh fingerprints for the starred set from current data maps.
133	 * A starred service missing from the current feed KEEPS its old fingerprint —
134	 * overwriting with nulls would silently destroy the "no longer listed" signal.
135	 */
136	export function refreshFingerprints(state, productsById, journeysById) {
137	  const fingerprints = Object.create(null);
138	  for (const id of state.starred) {
139	    fingerprints[id] = productsById.has(id)
140	      ? fingerprint(productsById.get(id), journeysById.get(id))
141	      : state.fingerprints?.[id] ?? fingerprint(undefined, undefined);
142	  }
143	  return { ...state, fingerprints };
144	}
145

