1	/** Pulse view: since-you-were-here card, animated tiles, live activity stream. */
2	
3	import { state, refreshLive, freshnessLabel, relativeDate } from '../data.js';
4	import { stackedColumns, barList } from '../charts.js';
5	import { countUp, esc, fmt, fmtOrDash } from '../ui.js';
6	import { fingerprint, diffFingerprints } from '../watchlist.js';
7	import { getWatchlist, commitFingerprints, markVisited, onWatchChange, openServiceDrawer } from './services.js';
8	
9	export function renderPulse() {
10	  renderWatchCard();
11	  renderTiles();
12	  renderStream();
13	  renderYearsChart();
14	  renderTopReused();
15	  document.getElementById('data-freshness').textContent = freshnessLabel();
16	  renderProvenance();
17	  wireLiveButton();
18	  onWatchChange(renderWatchCard); // Set-backed: same fn ref, registered once
19	}
20	
21	function renderProvenance() {
22	  const root = document.getElementById('data-provenance');
23	  if (!root) return;
24	  root.textContent = '';
25	  const sources = state.meta?.sources ?? {};
26	  const rows = [
27	    ['Marketplace', sources.marketplace],
28	    ['Changelog', sources.changelog],
29	    ['Rules', sources.rules],
30	  ].filter(([, source]) => source);
