227	 * Horizontal bar list (single series) with value labels at bar end.
228	 * data: [{label, sub, value}]
229	 */
230	export function barList(container, data, { format = (v) => String(v), caption = 'Chart data' } = {}) {
231	  container.innerHTML = '';
232	  hideTip();
233	  bindTipBackstop(container);
234	  if (!data.length) {
235	    renderEmptyState(container);
236	    return;
237	  }
238	  const rawMax = Math.max(...data.map((d) => Number(d.value) || 0));
239	  const max = Number.isFinite(rawMax) && rawMax > 0 ? rawMax : 0;
240	  for (const d of data) {
241	    const row = document.createElement('div');
242	    row.className = 'barlist-row';
243	    row.innerHTML = `
244	      <div class="barlist-label"><span class="barlist-name"></span><span class="barlist-sub"></span></div>
245	      <div class="barlist-track"><progress class="barlist-bar" aria-hidden="true"></progress><span class="barlist-value"></span></div>`;
246	    const bar = row.querySelector('.barlist-bar');
247	    bar.max = max || 1;
248	    bar.value = Math.max(0, Number(d.value) || 0);
249	    row.querySelector('.barlist-name').textContent = d.label;
250	    row.querySelector('.barlist-sub').textContent = d.sub ?? '';
251	    row.querySelector('.barlist-value').textContent = format(d.value);
252	    row.addEventListener('mousemove', () => showTip({
253	      title: d.label,
254	      lines: [d.sub ?? '', format(d.value)],
